3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// 计划状态：进行中的计划可改期、取消或完成；已完成与已取消均为终态，
11	// 不能再改期、取消或重新开启。
12	const (
13		PlanStatusOpen     = "未完成"
14		PlanStatusDone     = "已完成"
15		PlanStatusCanceled = "已取消"
16	)
17	
18	// 待办相对本机今天的标记。
19	const (
20		TodoToday   = "今天需校准"
21		TodoOverdue = "逾期"
22		TodoFuture  = "未到计划日"
23	)
24	
25	// PlanChange 记录一次改期：保留修改前后的日期、操作时间和原因。
26	type PlanChange struct {
27		From      string `json:"from"`
28		To        string `json:"to"`
29		ChangedAt string `json:"changed_at"`
30		Reason    string `json:"reason"`
31	}
32	
33	// Plan 是一项校准计划。编号在全台账唯一，即使计划已结束编号也不再复用。
34	type Plan struct {
35		Number       string `json:"number"`
36		InstrumentID string `json:"instrument_id"`
37		// PlannedDate 是当前计划日期；OriginalDate 保留建立时的计划日期。
38		PlannedDate  string       `json:"planned_date"`
39		OriginalDate string       `json:"original_date"`
40		Note         string       `json:"note"`
41		CreatedAt    string       `json:"created_at"`
42		Changes      []PlanChange `json:"changes,omitempty"`
43		Status       string       `json:"status"`
44		// 取消时保留原计划日期、取消时间和原因。
45		CanceledAt   string `json:"canceled_at,omitempty"`
46		CancelReason string `json:"cancel_reason,omitempty"`
47		// 完成时保存完成时间和所用证书编号。
48		CompletedAt       string `json:"completed_at,omitempty"`
49		CertificateNumber string `json:"certificate_number,omitempty"`
50	}
51	
52	// Open 报告计划是否尚未结束（未完成、未取消）。
53	func (p Plan) Open() bool { return p.Status == PlanStatusOpen }
54	
55	// PlanInput 是建立校准计划的输入。
56	type PlanInput struct {
57		Number       string
58		InstrumentID string
59		Date         string
60		Note         string
61	}
62	
63	func (l *Ledger) findPlan(number string) *Plan {
64		for i := range l.data.Plans {
65			if l.data.Plans[i].Number == number {
66				return &l.data.Plans[i]
67			}
68		}
69		return nil
70	}
71	
72	// validatePlanDate 解析 YYYY-MM-DD 真实日期，且不得早于本机今天。
73	func (l *Ledger) validatePlanDate(raw, field string) (string, error) {
74		_, text, err := parseFiniteDate(raw, field)
75		if err != nil {
76			return "", err
77		}
78		todayText := l.now().Format(DateLayout)
79		if text < todayText {
80			return "", validationError("%s %s 不能早于本机今天 %s", field, text, todayText)
81		}
82		return text, nil
83	}
84	
85	// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
86	// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
87	// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
88	// 不新增或改动任何记录。
89	func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
90		number, err := cleanText(in.Number)
91		if err != nil {
92			return nil, fmt.Errorf("计划编号无效：%w", err)
93		}
94		instID, err := cleanText(in.InstrumentID)
95		if err != nil {
96			return nil, fmt.Errorf("器具编号无效：%w", err)
97		}
98		note, err := cleanText(in.Note)
99		if err != nil {
100			return nil, fmt.Errorf("计划说明无效：%w", err)
101		}
102		if l.findInstrument(instID) == nil {
103			return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
104		}
105		dateText, err := l.validatePlanDate(in.Date, "计划日期")
106		if err != nil {
107			return nil, err
108		}
109		if l.findPlan(number) != nil {
110			return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
111		}
112		for i := range l.data.Plans {
113			p := &l.data.Plans[i]
114			if p.InstrumentID == instID && p.Open() {
115				return nil, validationError(
116					"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
117					instID, p.Number, p.PlannedDate)
118			}
119		}
120		p := Plan{
121			Number:       number,
122			InstrumentID: instID,
123			PlannedDate:  dateText,
124			OriginalDate: dateText,
125			Note:         note,
126			CreatedAt:    l.now().Format(time.RFC3339),
127			Status:       PlanStatusOpen,
128		}
129		l.data.Plans = append(l.data.Plans, p)
130		if err := l.save(); err != nil {
131			return nil, err
132		}
133		return l.findPlan(number), nil
134	}
135	
136	// requireOpenPlan 找到计划并确认其尚未结束；已结束计划返回明确的校验错误。
137	func (l *Ledger) requireOpenPlan(number string) (*Plan, error) {
138		p := l.findPlan(number)
139		if p == nil {
140			return nil, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
141		}
142		if !p.Open() {
143			return nil, validationError("计划 %s %s，已结束的计划不能再改期、取消或重新开启",
144				number, p.Status)
145		}
146		return p, nil
147	}
148	
149	// ReschedulePlan 改期一项未结束的计划。原因必须非空，新日期必须真实存在且
150	// 不早于操作当天；每次改期保留修改前后的日期、操作时间和原因。
151	// 找不到计划或计划已结束时拒绝且不改动记录。
152	func (l *Ledger) ReschedulePlan(number, newDate, reason string) (*Plan, error) {
153		number, err := cleanText(number)
154		if err != nil {
155			return nil, fmt.Errorf("计划编号无效：%w", err)
156		}
157		reason, err = cleanText(reason)
158		if err != nil {
159			return nil, fmt.Errorf("改期原因无效：%w", err)
160		}
161		dateText, err := l.validatePlanDate(newDate, "新计划日期")
162		if err != nil {
163			return nil, err
164		}
165		p, err := l.requireOpenPlan(number)
166		if err != nil {
167			return nil, err
168		}
169		// 即使新日期与当前日期相同也照常记录：保留修改前后的日期、操作时间和原因。
170		p.Changes = append(p.Changes, PlanChange{
171			From:      p.PlannedDate,
172			To:        dateText,
173			ChangedAt: l.now().Format(time.RFC3339),
174			Reason:    reason,
175		})
176		p.PlannedDate = dateText
177		if err := l.save(); err != nil {
178			return nil, err
179		}
180		return p, nil
181	}
182	
183	// CancelPlan 取消一项未结束的计划，原因必须非空。取消后保留原计划、取消时间
184	// 和原因，不再列入待办，也不能重新开启。找不到计划或计划已结束时拒绝。
185	func (l *Ledger) CancelPlan(number, reason string) (*Plan, error) {
186		number, err := cleanText(number)
187		if err != nil {
188			return nil, fmt.Errorf("计划编号无效：%w", err)
189		}
190		reason, err = cleanText(reason)
191		if err != nil {
192			return nil, fmt.Errorf("取消原因无效：%w", err)
193		}
194		p, err := l.requireOpenPlan(number)
195		if err != nil {
196			return nil, err
197		}
198		p.Status = PlanStatusCanceled
199		p.CanceledAt = l.now().Format(time.RFC3339)
200		p.CancelReason = reason
201		if err := l.save(); err != nil {
202			return nil, err
203		}
204		return p, nil
205	}
206	
207	// CompletePlan 用一张台账中已有的证书完成计划。证书必须属于该器具，校准日期
208	// 不得早于计划最初建立的本机日期，且未被用于完成其他计划。符合条件后保存
209	// 完成时间和证书编号；超差证书同样表示校准工作已完成。
210	//
211	// 再次用同一证书完成同一计划返回原结果，不增加记录或刷新完成时间；
212	// 已完成计划改用另一证书、证书不存在或不符合条件、完成已取消计划均拒绝。
213	func (l *Ledger) CompletePlan(number, certificateNumber string) (*Plan, bool, error) {
214		number, err := cleanText(number)
215		if err != nil {
216			return nil, false, fmt.Errorf("计划编号无效：%w", err)
217		}
218		certificateNumber, err = cleanText(certificateNumber)
219		if err != nil {
220			return nil, false, fmt.Errorf("证书编号无效：%w", err)
221		}
222		p := l.findPlan(number)
223		if p == nil {
224			return nil, false, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
225		}
226		// 幂等：同一证书再次完成同一计划，返回原结果，不刷新完成时间。
227		if p.Status == PlanStatusDone {
228			if p.CertificateNumber == certificateNumber {
229				return p, true, nil
230			}
231			return nil, false, validationError(
232				"计划 %s 已用证书 %s 完成，已完成计划不能改用另一证书",
233				number, p.CertificateNumber)
234		}
235		if p.Status == PlanStatusCanceled {
236			return nil, false, validationError("计划 %s 已取消，取消的计划不能完成；需要继续安排请建立新计划", number)
237		}
238	
239		cert := l.findCertificate(certificateNumber)
240		if cert == nil {
241			return nil, false, fmt.Errorf("证书编号 %s：%w", certificateNumber, ErrNotFound)
242		}
243		if cert.InstrumentID != p.InstrumentID {
244			return nil, false, validationError(
245				"证书 %s 属于器具 %s，不能用于完成器具 %s 的计划 %s",
246				certificateNumber, cert.InstrumentID, p.InstrumentID, number)
247		}
248		// 计划建立的本机日期：CreatedAt 是 RFC3339，取其日历日期；与证书校准日期
249		// 按日历日期比较，校准日期不得早于该日期（等于可以）。
250		created, perr := time.Parse(time.RFC3339, p.CreatedAt)
251		if perr != nil {
252			return nil, false, fmt.Errorf("计划 %s 建立时间已损坏: %w", number, perr)
253		}
254		createdDay := created.Format(DateLayout)
255		if cert.CalDate < createdDay {
256			return nil, false, validationError(
257				"证书 %s 的校准日期 %s 早于计划 %s 的建立日期 %s，不能用于完成该计划",
258				certificateNumber, cert.CalDate, number, createdDay)
259		}
260		// 同一证书不能用于完成两项计划；以幂等方式再次完成本计划已在前面处理。
261		for i := range l.data.Plans {
262			other := &l.data.Plans[i]
263			if other.Number != number && other.Status == PlanStatusDone &&
264				other.CertificateNumber == certificateNumber {
265				return nil, false, validationError(
266					"证书 %s 已用于完成计划 %s，不能再用于完成其他计划",
267					certificateNumber, other.Number)
268			}
269		}
270	
271		p.Status = PlanStatusDone
272		p.CompletedAt = l.now().Format(time.RFC3339)
273		p.CertificateNumber = certificateNumber
274		if err := l.save(); err != nil {
275			return nil, false, err
276		}
277		return p, false, nil
278	}
279	
280	// TodoItem 是待办查询中的一项计划及其按本机日期重新判断的标记。
281	type TodoItem struct {
282		PlanNumber     string `json:"plan_number"`
283		InstrumentID   string `json:"instrument_id"`
284		InstrumentName string `json:"instrument_name"`
285		Status         Status `json:"status"`
286		PlannedDate    string `json:"planned_date"`
287		Note           string `json:"note"`
288		Marker         string `json:"marker"`
289	}
290	
291	// planMarker 按计划日期相对今天给出标记：今天“今天需校准”，已过“逾期”，
292	// 未来“未到计划日”。
293	func planMarker(plannedDate, todayText string) string {
294		switch {
295		case plannedDate < todayText:
296			return TodoOverdue
297		case plannedDate == todayText:
298			return TodoToday
299		default:
300			return TodoFuture
301		}
302	}
303	
304	// Todos 列出未结束的计划作为待办。instrumentID 为空时列出全部器具的待办，
305	// 否则只列该器具（器具不存在时报 ErrNotFound）。结果按计划日期从早到晚、
306	// 同日按器具编号排列。查询不产生任何使用记录或写盘。
307	func (l *Ledger) Todos(instrumentID string) ([]TodoItem, error) {
308		id := strings.TrimSpace(instrumentID)
309		if id != "" && l.findInstrument(id) == nil {
310			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
311		}
312		todayText := l.now().Format(DateLayout)
313		items := []TodoItem{}
314		for _, p := range l.data.Plans {
315			if !p.Open() {
316				continue
317			}
318			if id != "" && p.InstrumentID != id {
319				continue
320			}
321			inst := l.findInstrument(p.InstrumentID)
322			if inst == nil {
323				continue
324			}
325			items = append(items, TodoItem{
326				PlanNumber:     p.Number,
327				InstrumentID:   inst.ID,
328				InstrumentName: inst.Name,
329				Status:         inst.Status,
330				PlannedDate:    p.PlannedDate,
331				Note:           p.Note,
332				Marker:         planMarker(p.PlannedDate, todayText),
333			})
334		}
335		sort.Slice(items, func(i, j int) bool {
336			if items[i].PlannedDate != items[j].PlannedDate {
337				return items[i].PlannedDate < items[j].PlannedDate
338			}
339			return items[i].InstrumentID < items[j].InstrumentID
340		})
341		return items, nil
342	}
343	
344	// PlanView 是计划的完整视图，供按器具核对时展示当前与已结束计划、
345	// 改期记录和关联证书编号。
346	type PlanView struct {
347		Plan
348		Marker string `json:"marker"`
349	}
350	
351	// plansOf 返回某器具的全部计划（含已结束），按建立先后排列。
352	func (l *Ledger) plansOf(id string) []Plan {
353		var out []Plan
354		for _, p := range l.data.Plans {
355			if p.InstrumentID == id {
356				out = append(out, p)
357			}
358		}
359		sort.SliceStable(out, func(i, j int) bool { return out[i].CreatedAt < out[j].CreatedAt })
360		return out
361	}
362	
363	// planViews 构造器具核对用的计划视图；标记仅对未结束计划有意义。
364	func (l *Ledger) planViews(id string, today time.Time) []PlanView {
365		todayText := today.Format(DateLayout)
366		plans := l.plansOf(id)
367		out := make([]PlanView, 0, len(plans))
368		for _, p := range plans {
369			v := PlanView{Plan: p}
370			if p.Open() {
371				v.Marker = planMarker(p.PlannedDate, todayText)
372			}
373			out = append(out, v)
374		}
375		return out
376	}
377	
378	// Plans 返回某器具的全部计划（含已结束），按建立先后排列；
379	// 器具不存在时报 ErrNotFound。
380	func (l *Ledger) Plans(instrumentID string) ([]PlanView, error) {
381		id := strings.TrimSpace(instrumentID)
382		inst := l.findInstrument(id)
383		if inst == nil {
384			return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
385		}
386		return l.planViews(id, l.now()), nil
387	}
388

