		t.Fatalf("应保留已结束计划：%+v", r.Plans)
	}
	p := r.Plans[0]
	if p.Status != PlanStatusCanceled || p.CancelReason != "暂停送检" || p.CanceledAt == "" {
		t.Fatalf("已取消计划应保留原状态与取消信息：%+v", p)
	}
	if p.Marker != "" {
		t.Fatalf("已结束计划不应带待办标记：%q", p.Marker)
	}
}

